import random
import itertools
import sys
from problems import ThreeSat, SubsetSum
from reduce import reduce

def solve_three_sat_bruteforce(instance):
    m = instance["num_vars"]
    clauses = instance["clauses"]
    # Edge case: no clauses -> yes
    if not clauses:
        return True
    for bits in range(1 << m):
        ok = True
        for clause in clauses:
            clause_ok = False
            for lit in clause:
                var = abs(lit) - 1
                val = (bits >> var) & 1
                if lit > 0 and val == 1:
                    clause_ok = True
                if lit < 0 and val == 0:
                    clause_ok = True
            if not clause_ok:
                ok = False
                break
        if ok:
            return True
    return False

def solve_subset_sum_bruteforce(instance):
    numbers = instance["numbers"]
    target = instance["target"]
    n = len(numbers)
    # simple subset enumeration
    for r in range(n+1):
        for combo in itertools.combinations(range(n), r):
            s = sum(numbers[i] for i in combo)
            if s == target:
                return True
    return False

def random_three_sat(max_vars=4, max_clauses=4):
    m = random.randint(0, max_vars)
    # ensure if clauses exist, m>=3 per spec but we can still generate smaller for testing
    num_clauses = random.randint(0, max_clauses)
    clauses = []
    for _ in range(num_clauses):
        # pick 3 distinct vars (if possible)
        if m == 0:
            break
        vars = random.sample(range(1, m+1), k=min(3, m))
        # if less than 3 distinct vars, pad with repeats? avoid, just continue
        if len(vars) < 3:
            continue
        clause = []
        for v in vars:
            lit = v if random.choice([True, False]) else -v
            clause.append(lit)
        clauses.append(clause)
    return {"num_vars": m, "clauses": clauses}

def main():
    random.seed(0)
    tests = 200
    passed = 0
    for i in range(tests):
        inst = random_three_sat()
        # validate
        ThreeSat.validate(inst)
        reduced = reduce(inst)
        SubsetSum.validate(reduced)
        ans1 = solve_three_sat_bruteforce(inst)
        ans2 = solve_subset_sum_bruteforce(reduced)
        if ans1 == ans2:
            passed += 1
        else:
            print("Mismatch!", inst, reduced, ans1, ans2)
            sys.exit(1)
    print(f"All {passed}/{tests} tests passed.")

if __name__ == "__main__":
    main()
EOF"}

